CREATE TABLE companion_devices (id TEXT PRIMARY KEY, created_by TEXT NOT NULL REFERENCES users(id), label TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('pending','active','revoked')), code_hash TEXT NOT NULL UNIQUE, code_expires_at_ms INTEGER NOT NULL, token_hash TEXT UNIQUE, expires_at_ms INTEGER NOT NULL, active_capture_id TEXT REFERENCES capture_sessions(id), ready_capture_id TEXT REFERENCES capture_sessions(id), binding_revision INTEGER NOT NULL DEFAULT 0, created_at_ms INTEGER NOT NULL, last_seen_at_ms INTEGER);
CREATE INDEX companion_devices_owner ON companion_devices(created_by,status);
CREATE TABLE companion_device_guards (operation_id TEXT PRIMARY KEY, device_id TEXT NOT NULL, token_hash TEXT NOT NULL, capture_id TEXT, now_ms INTEGER NOT NULL);
CREATE TRIGGER companion_device_permission BEFORE INSERT ON companion_device_guards WHEN NOT EXISTS(SELECT 1 FROM companion_devices d JOIN access_effective_permissions a ON a.user_id=d.created_by WHERE d.id=NEW.device_id AND d.token_hash=NEW.token_hash AND d.status='active' AND d.expires_at_ms>NEW.now_ms AND json_type(a.permissions_json,'$.captures')='integer' AND json_extract(a.permissions_json,'$.captures')=3 AND (NEW.capture_id IS NULL OR EXISTS(SELECT 1 FROM capture_sessions c JOIN access_effective_permissions ca ON ca.user_id=c.created_by WHERE c.id=NEW.capture_id AND c.id=d.active_capture_id AND c.created_by=d.created_by AND c.status='open' AND c.expires_at_ms>NEW.now_ms AND json_type(ca.permissions_json,'$.captures')='integer' AND json_extract(ca.permissions_json,'$.captures')=3))) BEGIN SELECT RAISE(ABORT,'COMPANION_DEVICE_DENIED'); END;
